window.AUTH=window.AUTH||{};window.AUTH["99-5153"]={"d":"99-5153","id":"1999/99-5153","n":"Johnson v. United States","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the United States","date":"","url":"https://www.justice.gov/osg/media/226171/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/cornell-johnson-v-united-states-merits","n":69}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep529/usrep529694/usrep529694.pdf","tr":false,"items":[{"t":"case","label":"Artuso v. Hall","cite":"74 F.3d 68","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/74/68/","by":{"0":"34"}},{"t":"case","label":"Billis v. United States","cite":"83 F.3d 209","y":1996,"url":"https://www.courtlistener.com/c/F.3d/83/209/","by":{"0":"34"}},{"t":"case","label":"Bouie v. City of Columbia","cite":"378 U.S. 347","y":1964,"id":"1963/10","sc":1,"sum":"The State Supreme Court, in giving retroactive application to its new construction of the statute, has deprived petitioners of their right to fair warning of a criminal prohibition, and thus has violated the Due Process Clause of the Fourteenth Amendment. Pp. 348-363. 239 S. C. 570, 124 S. E. 2d 332, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"sum":"The Court held that, although Bousley's claim was procedurally defaulted, Bousley may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Brown v. GSA","cite":"425 U.S. 820","y":1976,"id":"1975/74-768","sc":1,"sum":"Section 717 provides the exBROWN v. GSA","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"California Dep’t of Corrections v. Morales","cite":"514 U.S. 499","y":1995,"id":"1994/93-1462","sc":1,"op":1,"sum":"The amendment's application to prisoners who committed their crimes before it was enacted does not violate the Ex Post Facto Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 45"}},{"t":"case","label":"Chapman v. California","cite":"386 U.S. 18","y":1967,"id":"1966/95","sc":1,"op":1,"sum":"Justice Black determined that federal law must govern the application of a state harmless error rule; the Court cannot leave the formulation of rules protecting individuals from invasion by the states to those very same states.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Cisneros v. Alpine Ridge Group","cite":"508 U.S. 10","y":1993,"id":"1992/92-551","sc":1,"op":1,"sum":"This Court need not consider whether §801 of the Reform Act unconstitutionally abrogated a contract right to unobstructed formulabased rent adjustments, since respondents have no such right. The assistance contracts do not prohibit the use of comparability studies to impose an independent cap on such adjustments. Indeed, § 1.9d's plain Cite as: 508 U. S. 10 (1993) language clearly mandates that contract rents \"shall …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Evans v. United States Parole Comm’n","cite":"78 F.3d 262","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/78/262/","op":1,"by":{"0":"34"}},{"t":"case","label":"Fowler v. United States Parole Comm’n","cite":"94 F.3d 835","y":1996,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/94/835/","by":{"0":"34"}},{"t":"case","label":"Gozlon-Peretz v. United States","cite":"498 U.S. 395","y":1991,"id":"1990/89-7370","sc":1,"op":3,"sum":"Supervised release applies for all drug offenses in the categories specified by ADAA § 1002 that were committed after the ADAA was enacted but before November 1, 1987.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Lindsey v. Washington","cite":"301 U.S. 397","y":1937,"id":"scdb/1936-123","sc":1,"sum":"A state statute making more onerous the standard of punishment is ex post facto and void as applied to a crime committed before its enactment. P.:401. Under the law of the State of Washington at the time of the alleged offense, imprisonment of the accused could have been fixed by the judge at less than the maximum of 15 years. By the law as amended and applied (c. 114, L. Wash., 1935), sentence for 15 years was made …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 38, 40"}},{"t":"case","label":"Lockhart v. Fretwell","cite":"506 U.S. 364","y":1993,"id":"1992/91-1393","sc":1,"sum":"Counsel's failure to make the Collins objection during the sentencing proceeding did not constitute prejudice within the meaning of Strickland v. Washington, supra. To show prejudice under Strickland, a defendant must demonstrate that counsel's errors are so serious as to deprive him of a trial whose result is unfair or unreliable, id., at 687, not merely that the outcome would have been different. Unfairness or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Lynce v. Mathis","cite":"519 U.S. 433","y":1997,"id":"1996/95-7452","sc":1,"op":1,"sum":"The Court ruled that the 1992 statute canceling provisional release credits violates the Ex Post Facto Clause of the Federal Constitution.","sumSrc":"Oyez","by":{"0":"17, 35, 38, 39"}},{"t":"case","label":"Marks v. United States","cite":"430 U.S. 188","y":1977,"id":"1976/75-708","sc":1,"sum":"The Due Process Clause of the Fifth Amendment precludes retroactive application to petitioners of the Miller standards, to the extent that those standards may impose criminal liability for conduct not punishable under the standards announced in Memoirs v. Massachusetts, 383 U. S. 413. Bouie v. City of Columbia, 378 U. S. 347. Specifically, petitioners are entitled to jury instructions requiring the jury to acquit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Memoirs v. Massachusetts","cite":"383 U.S. 413","y":1966,"id":"1965/368","sc":1,"sum":"The Court held that the Massachusetts courts erred in finding Memoirs of a Woman of Pleasure to be obscene.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Miller v. California","cite":"413 U.S. 15","y":1973,"id":"1971/70-73","sc":1,"sum":"The Court found that \"obscene materials\" do not have First Amendment protection.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Miller v. Florida","cite":"482 U.S. 423","y":1987,"id":"1986/86-5344","sc":1,"sum":"Application of the revised guidelines law to petitioner, whose crimes occurred before the law's effective date, violates the Ex Post Facto Clause of Article I of the Federal Constitution. The revised law evidences all of the elements necessary to bring it within the ex post facto prohibition.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 39"}},{"t":"case","label":"Moody v. Daggett","cite":"429 U.S. 78","y":1976,"id":"1976/74-6632","sc":1,"sum":"Petitioner federal parolee, imprisoned for federal crimes committed while on parole and clearly constituting parole violations, held not to be constitutionally entitled to an immediate parole revocation hearing, where a parole violator warrant was issued and lodged with the institution of his confinement as a \"detainer\" but was not executed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"op":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 20"}},{"t":"case","label":"Robles v. United States","cite":"146 F.3d 1098","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/146/1098/","by":{"0":"34"}},{"t":"case","label":"State v. Callahan","cite":"109 La. 946","y":1903,"url":"https://www.courtlistener.com/c/La./109/946/","by":{"0":"40"}},{"t":"case","label":"Tome v. United States","cite":"513 U.S. 150","y":1995,"id":"1994/93-6892","sc":1,"sum":"The Court held that Rule 801(d)(1)(B) requires that prior consistent statements be made before the motive to fabricate arose in order to be admissible.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"United States v. Barton","cite":"26 F.3d 490","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/26/490/","by":{"0":"43"}},{"t":"case","label":"United States v. Behnezhad","cite":"907 F.2d 896","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/907/896/","op":1,"by":{"0":"37"}},{"t":"case","label":"United States v. Cooper","cite":"962 F.2d 339","y":1992,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/962/339/","op":1,"by":{"0":"7, 30"}},{"t":"case","label":"United States v. Davis","cite":"151 F.3d 1304","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/151/1304/","by":{"0":"11"}},{"t":"case","label":"United States v. Davis","cite":"187 F.3d 528","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/187/528/","by":{"0":"31"}},{"t":"case","label":"United States v. Edgin","cite":"92 F.3d 1044","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/92/1044/","by":{"0":"27"}},{"t":"case","label":"United States v. Eng","cite":"14 F.3d 165","y":1994,"url":"https://www.courtlistener.com/c/F.3d/14/165/","by":{"0":"11"}},{"t":"case","label":"United States v. Garcia","cite":"112 F.3d 395","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/112/395/","by":{"0":"22"}},{"t":"case","label":"United States v. LeMay","cite":"952 F.2d 995","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/952/995/","by":{"0":"43"}},{"t":"case","label":"United States v. Neville","cite":"985 F.2d 992","y":1993,"url":"https://www.courtlistener.com/c/F.2d/985/992/","by":{"0":"43"}},{"t":"case","label":"United States v. O’Neil","cite":"11 F.3d 292","y":1993,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/11/292/","op":5,"sum":"Observing that “the supervision term recommenced upon revocation–-else there would be no term then in existence” before the offender to serve in prison.","sumSrc":"brief:0","by":{"0":"7, 24, 25, 32, 33"}},{"t":"case","label":"United States v. Orozco-Rodriguez","cite":"60 F.3d 705","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/60/705/","by":{"0":"13, 17"}},{"t":"case","label":"United States v. Robinson","cite":"106 F.3d 610","y":1997,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/106/610/","by":{"0":"34"}},{"t":"case","label":"United States v. Rockwell","cite":"984 F.2d 1112","y":1993,"url":"https://www.courtlistener.com/c/F.2d/984/1112/","op":1,"by":{"0":"7, 8"}},{"t":"case","label":"United States v. Rodgers","cite":"466 U.S. 475","y":1984,"id":"1983/83-620","sc":1,"sum":"The language of § 1001 clearly encompasses criminal investigations conducted by the FBI and Secret Service, and nothing in the legislative history indicates that Congress intended a more restrictive reach for the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"United States v. Schechter","cite":"13 F.3d 1117","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/13/1117/","by":{"0":"27"}},{"t":"case","label":"United States v. Shorty","cite":"159 F.3d 312","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/159/312/","by":{"0":"20"}},{"t":"case","label":"United States v. Tatum","cite":"998 F.2d 893","y":1993,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/998/893/","op":1,"by":{"0":"7, 8"}},{"t":"case","label":"United States v. Truss","cite":"4 F.3d 437","y":1993,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/4/437/","op":2,"by":{"0":"7, 8, 19, 23, 24"}},{"t":"case","label":"United States v. Williams","cite":"2 F.3d 363","y":1993,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/2/363/","by":{"0":"8, 23"}},{"t":"case","label":"United States v. Withers","cite":"128 F.3d 1167","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/128/1167/","op":1,"by":{"0":"45"}},{"t":"case","label":"United States Parole Comm’n v. Williams","cite":"54 F.3d 820","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/54/820/","op":1,"sum":"Noting \"the established preGuidelines sentencing principle that parole is available unless expressly precluded\" (citation and internal quotation marks omitted).","sumSrc":"opinion","by":{"0":"32, 34"}},{"t":"case","label":"Weaver v. Graham","cite":"450 U.S. 24","y":1981,"id":"1980/79-5780","sc":1,"sum":"Held.: A Florida statute repealing an earlier statute and reducing the amount of \"gain time\" for good conduct and obedience to prison rules deducted from a convicted prisoner's sentence is unconstitutional as an ex post facto law as applied to petitioner, whose crime was committed before the statute's enactment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 37, 38, 39"}},{"t":"const","label":"Article I, Section 9, Clause 3","clauses":[["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"]],"text":"No Bill of Attainder or ex post facto Law shall be passed.","by":{"0":"passim"}},{"t":"law","label":"Pub. L. No. 100-690","url":"https://www.govinfo.gov/link/statute/102/4419","by":{"0":"25"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"0":"22"}},{"t":"usc","label":"18 U.S.C. § 1029","url":"https://www.law.cornell.edu/uscode/text/18/1029","subs":["(b)(2)","(c)(1)(A)(i)"],"stext":{"head":"§1029. Fraud and related activity in connection with access devices","paras":[[0,"(a) Whoever—"],[1,"(1) knowingly and with intent to defraud produces, uses, or traffics in one or more counterfeit access devices;"],[1,"(2) knowingly and with intent to defraud traffics in or uses one or more unauthorized access devices during any one-year period, and by such conduct obtains anything of value aggregating $1,000 or more during that period;"],[1,"(3) knowingly and with intent to defraud possesses fifteen or more devices which are counterfeit or unauthorized access devices;"],[1,"(4) knowingly, and with intent to defraud, produces, traffics in, has control or custody of, or possesses device-making equipment;"],[1,"(5) knowingly and with intent to defraud effects transactions, with 1 or more access devices issued to another person or persons, to receive payment or any other thing of value during any 1-year period the aggregate value of which is equal to or greater than $1,000;"],[1,"(6) without the authorization of the issuer of the access device, knowingly and with intent to defraud solicits a person for the purpose of—"],[2,"(A) offering an access device; or"],[2,"(B) selling information regarding or an application to obtain an access device;"],[1,"(7) knowingly and with intent to defraud uses, produces, traffics in, has control or custody of, or possesses a telecommunications instrument that has been modified or altered to obtain unauthorized use of telecommunications services;"],[1,"(8) knowingly and with intent to defraud uses, produces, traffics in, has control or custody of, or possesses a scanning receiver;"],[1,"(9) knowingly uses, produces, traffics in, has control or custody of, or possesses hardware or software, knowing it has been configured to insert or modify telecommunication identifying information associated with or contained in a telecommunications instrument so that such instrument may be used to obtain telecommunications service without authorization; or"],[1,"(10) without the authorization of the credit card system member or its agent, knowingly and with intent to defraud causes or arranges for another person to present to the member or its agent, for payment, 1 or more evidences or records of transactions made by an access device;"],[0,"shall, if the offense affects interstate or foreign commerce, be punished as provided in subsection (c) of this section."],[0,"(b)(1) Whoever attempts to commit an offense under subsection (a) of this section shall be subject to the same penalties as those prescribed for the offense attempted."],[0,"(2) Whoever is a party to a conspiracy of two or more persons to commit an offense under subsection (a) of this section, if any of the parties engages in any conduct in furtherance of such offense, shall be fined an amount not greater than the amount provided as the maximum fine for such offense under subsection (c) of this section or imprisoned not longer than one-half the period provided as the maximum imprisonment for such offense under subsection (c) of this section, or both."],[0,"(c) Penalties.—"],[1,"(1) Generally.—The punishment for an offense under subsection (a) of this section is—"],[2,"(A) in the case of an offense that does not occur after a conviction for another offense under this section—"],[3,"(i) if the offense is under paragraph (1), (2), (3), (6), (7), or (10) of subsection (a), a fine under this title or imprisonment for not more than 10 years, or both; and"],[3,"(ii) if the offense is under paragraph (4), (5), (8), or (9) of subsection (a), a fine under this title or imprisonment for not more than 15 years, or both;"],[2,"(B) in the case of an offense that occurs after a conviction for another offense under this section, a fine under this title or imprisonment for not more than 20 years, or both; and"],[2,"(C) in either case, forfeiture to the United States of any personal property used or intended to be used to commit the offense."],[1,"(2) Forfeiture procedure.—The forfeiture of property under this section, including any seizure and disposition of the property and any related administrative and judicial proceeding, shall be governed by section 413 of the Controlled Substances Act, except for subsection (d) of that section."],[0,"(d) The United States Secret Service shall, in addition to any other agency having such authority, have the authority to investigate offenses under this section. Such authority of the United States Secret Service shall be exercised in accordance with an agreement which shall be entered into by the Secretary of the Treasury and the Attorney General."],[0,"(e) As used in this section—"],[1,"(1) the term \"access device\" means any card, plate, code, account number, electronic serial number, mobile identification number, personal identification number, or other telecommunications service, equipment, or instrument identifier, or other means of account access that can be used, alone or in conjunction with another access device, to obtain money, goods, services, or any other thing of value, or that can be used to initiate a transfer of funds (other than a transfer originated solely by paper instrument);"],[1,"(2) the term \"counterfeit access device\" means any access device that is counterfeit, fictitious, altered, or forged, or an identifiable component of an access device or a counterfeit access device;"],[1,"(3) the term \"unauthorized access device\" means any access device that is lost, stolen, expired, revoked, canceled, or obtained with intent to defraud;"],[1,"(4) the term \"produce\" includes design, alter, authenticate, duplicate, or assemble;"],[1,"(5) the term \"traffic\" means transfer, or otherwise dispose of, to another, or obtain control of with intent to transfer or dispose of;"],[1,"(6) the term \"device-making equipment\" means any equipment, mechanism, or impression designed or primarily used for making an access device or a counterfeit access device;"],[1,"(7) the term \"credit card system member\" means a financial institution or other entity that is a member of a credit card system, including an entity, whether affiliated with or identical to the credit card issuer, that is the sole member of a credit card system;"],[1,"(8) the term \"scanning receiver\" means a device or apparatus that can be used to intercept a wire or electronic communication in violation of chapter 119 or to intercept an electronic serial number, mobile identification number, or other identifier of any telecommunications service, equipment, or instrument;"],[1,"(9) the term \"telecommunications service\" has the meaning given such term in section 3 of title I of the Communications Act of 1934 (47 U.S.C. 153);"],[1,"(10) the term \"facilities-based carrier\" means an entity that owns communications transmission facilities, is responsible for the operation and maintenance of those facilities, and holds an operating license issued by the Federal Communications Commission under the authority of title III of the Communications Act of 1934; and"],[1,"(11) the term \"telecommunication identifying information\" means electronic serial number or any other number or signal that identifies a specific telecommunications instrument or account, or a specific communication transmitted from a telecommunications instrument."],[0,"(f) This section does not prohibit any lawfully authorized investigative, protective, or intelligence activity of a law enforcement agency of the United States, a State, or a political subdivision of a State, or of an intelligence agency of the United States, or any activity authorized under chapter 224 of this title. For purposes of this subsection, the term \"State\" includes a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States."],[0,"(g)(1) It is not a violation of subsection (a)(9) for an officer, employee, or agent of, or a person engaged in business with, a facilities-based carrier, to engage in conduct (other than trafficking) otherwise prohibited by that subsection for the purpose of protecting the property or legal rights of that carrier, unless such conduct is for the purpose of obtaining telecommunications service provided by another facilities-based carrier without the authorization of such carrier."],[0,"(2) In a prosecution for a violation of subsection (a)(9), (other than a violation consisting of producing or trafficking) it is an affirmative defense (which the defendant must establish by a preponderance of the evidence) that the conduct charged was engaged in for research or development in connection with a lawful purpose."],[0,"(h) Any person who, outside the jurisdiction of the United States, engages in any act that, if committed within the jurisdiction of the United States, would constitute an offense under subsection (a) or (b) of this section, shall be subject to the fines, penalties, imprisonment, and forfeiture provided in this title if the offense involves an access device issued, owned, managed, or controlled by a financial institution, account issuer, credit card system member, or other entity organized under the laws of the United States, or any State, the District of Columbia, or other territory of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1029?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1029. Fraud and related activity in connection with access devices","tname":"Crimes and Criminal Procedure","by":{"0":"10, 10"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3559","url":"https://www.law.cornell.edu/uscode/text/18/3559","subs":["(a)(4)"],"by":{"0":"10"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(b)"],"by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(a)","(b)","(d)","(e)(1)","(e)(2)","(e)(3)","(e)(4)","(h)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"op":12,"head":"§3583. Inclusion of a term of supervised release after imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"2, 36, 2, 36, 3, 10, 29, 30, 37, 18, 24, 27, 28, 30, 27, 30, 45, passim, 18, passim"}},{"t":"usc","label":"18 U.S.C. § 3603","url":"https://www.law.cornell.edu/uscode/text/18/3603","subs":["(2)"],"by":{"0":"11"}},{"t":"usc","label":"18 U.S.C. § 3653","url":"https://www.law.cornell.edu/uscode/text/18/3653","subs":["(1982)"],"op":2,"tname":"Crimes and Criminal Procedure","by":{"0":"32"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"0":"30, 21"}},{"t":"reg","label":"28 C.F.R. § 2.57","url":"https://www.ecfr.gov/current/title-28/section-2.57","subs":["(c)"],"by":{"0":"34"}}]};